// Reads last processed update_id so we never re-handle old messages.
// NOTE: static data persists only while the workflow is ACTIVE (production runs).
const s = $getWorkflowStaticData('global');
const offset = s.lastUpdateId ? s.lastUpdateId + 1 : 0;
return [{ json: { offset, botToken: $env.TELEGRAM_BOT_TOKEN } }];

// Telegram: voice note, forwarded/uploaded audio, PHOTO, or typed text report.
// Dedupe: processed message keys tracked in static data (poll restarts re-deliver).
const s = $getWorkflowStaticData('global');
const updates = $input.first().json.result ?? [];
if (updates.length) {
  s.lastUpdateId = Math.max(...updates.map(u => u.update_id));
}
s.processedMsgs = s.processedMsgs ?? {};
const out = [];
for (const u of updates) {
  const m = u.message;
  if (!m) continue;
  const key = 'tg:' + m.chat.id + ':' + m.message_id;
  const replyKey = m.reply_to_message?.message_id ? 'tg:' + m.chat.id + ':' + m.reply_to_message.message_id : null;
  if (s.processedMsgs[key]) continue;
  const media = m.voice ?? m.audio;
  // photo arrives as an array of sizes, smallest first — the last one is the
  // largest Telegram kept, and OCR of a handwritten page needs every pixel.
  const photo = Array.isArray(m.photo) && m.photo.length ? m.photo[m.photo.length - 1] : null;
  // "send as file" keeps full resolution and arrives as a document instead.
  const imageDoc = m.document && String(m.document.mime_type ?? '').startsWith('image/') ? m.document : null;
  const base = {
    channel: 'telegram',
    chat_id: m.chat.id,
    message_id: m.message_id,
    user_id: String(m.from?.id),
    is_forwarded: Boolean(m.forward_date || m.forward_origin),
    technicien: m.from?.first_name ?? String(m.from?.id),
    caption: m.caption ?? null,
    msg_key: key,
    reply_to: replyKey,
  };
  if (media) {
    s.processedMsgs[key] = true;
    out.push({ json: { ...base, kind: 'audio', file_ref: media.file_id } });
  } else if (photo || imageDoc) {
    s.processedMsgs[key] = true;
    out.push({ json: { ...base, kind: 'image', file_ref: (photo ?? imageDoc).file_id } });
  } else if (m.text && !m.text.startsWith('/')) {
    // A typed report. Bot commands are ignored outright since 2026-08-15:
    // /rapport, /modify and /supprimer were removed, and /start never had
    // a handler, so anything starting with a slash is not a report.
    s.processedMsgs[key] = true;
    out.push({ json: { ...base, kind: 'text', text_input: m.text, file_ref: null } });
  }
}
return out;

// WhatsApp Cloud API webhook payload (manual webhook: wrapped in body).
// Voice notes and forwarded audio both arrive as type 'audio'. Photos arrive as
// type 'image'. Text reports supported.
// Dedupe: Meta retries webhook deliveries on slow/failed responses.
const s = $getWorkflowStaticData('global');
s.processedMsgs = s.processedMsgs ?? {};
const out = [];
for (const item of $input.all()) {
  for (const entry of item.json.body?.entry ?? []) {
    for (const change of entry.changes ?? []) {
      const v = change.value;
      const contactName = v?.contacts?.[0]?.profile?.name;
      for (const m of v?.messages ?? []) {
        const key = 'wa:' + m.id;
        const replyKey = m.context?.id ? 'wa:' + m.context.id : null;
        if (s.processedMsgs[key]) continue;
        const base = {
          channel: 'whatsapp',
          chat_id: m.from,
          message_id: m.id,
          user_id: String(m.from),
          is_forwarded: Boolean(m.context?.forwarded),
          technicien: contactName ?? m.from,
          caption: m.audio?.caption ?? m.image?.caption ?? null,
          msg_key: key,
          reply_to: replyKey,
        };
        if (m.type === 'audio' && m.audio?.id) {
          s.processedMsgs[key] = true;
          out.push({ json: { ...base, kind: 'audio', file_ref: m.audio.id } });
        } else if (m.type === 'image' && m.image?.id) {
          s.processedMsgs[key] = true;
          out.push({ json: { ...base, kind: 'image', file_ref: m.image.id } });
        } else if (m.type === 'text' && m.text?.body) {
          s.processedMsgs[key] = true;
          out.push({ json: { ...base, kind: 'text', text_input: m.text.body, file_ref: null } });
        }
      }
    }
  }
}
return out;

// Single named source for the authorization branch.
// Both channels merge here, so the code node after the lookup can pair a
// lookup response back to its message with $('Sender').itemMatching(i).
// The allowlist itself is NOT here: it lives in the `technicians` table
// the dashboard writes to, and is read by the next node.
return $input.all();

// Stable reference point for downstream nodes regardless of the
// audio/text path.
//
// It deliberately does NOT re-join the answer to its message. That was
// tried on 2026-08-15 on the theory that pairedItem did not survive the
// media branch; it does, and routing the reply's chat_id/message_id
// through here instead of $('Filtrer accès') is what stopped WhatsApp
// rendering the quoted original. The message fields have one source.
return $input.all();

// One trace id per message, threaded through every stage so the six
// per-message log rows (and the API's own errors, logged from a
// different process) join into one story in the dashboard.
return $input.all().map(item => ({
  json: {
    ...item.json,
    correlation_id: item.json.correlation_id
      ?? `${item.json.channel}-${item.json.message_id ?? Date.now()}`,
  },
}));

// The claim call replaced each payload with {fresh}; re-attach the original
// message index-wise (an HTTP node emits one output per input, in order) and
// carry the flag forward so the IF filters real messages, not bare booleans.
// Explicit pairedItem keeps $('Filtrer accès').item resolvable for batches.
const src = $('Correlate').all();
return $input.all().map((item, i) => ({
  json: { ...src[i].json, fresh: item.json.fresh !== false },
  pairedItem: { item: i },
}));

// Authorization from the `technicians` table (dashboard-managed), not
// from a literal in this workflow. GET /technicians/lookup already
// filters on `active`, so a technician deactivated in the dashboard
// stops being authorized on the next message.
const s = $getWorkflowStaticData('global');
s.hrRepliedTo = s.hrRepliedTo ?? {};
const out = [];
const results = $input.all();
for (let i = 0; i < results.length; i++) {
  const msg = $('Sender').itemMatching(i).json;
  const tech = results[i].json.found ? results[i].json.technician : null;
  const dedupeKey = msg.channel + ':' + msg.chat_id;
  if (tech) {
    out.push({ json: { ...msg, technicien: tech.name, role: tech.role, authorized: true } });
  } else if (!s.hrRepliedTo[dedupeKey]) {
    // Outsider: exactly ONE automated HR-contact reply per chat, then silence.
    s.hrRepliedTo[dedupeKey] = true;
    out.push({ json: { ...msg, authorized: false } });
  }
}
return out;

// Flatten n8n's error payload into one pipeline_logs row.
// Payload shape: { workflow: {id,name}, execution: {id,url,error,lastNodeExecuted,...} }
// Goes to Postgres, NOT the Sheet: an error handler that writes to Google
// cannot report the failure of writing to Google.
const e = $input.first().json;
const err = e.execution?.error ?? {};
return [{
  json: {
    stage: 'workflow_error',
    level: 'error',
    message: err.message ?? String(err),
    correlation_id: null,
    channel: null,
    technicien: null,
    payload: {
      workflow: e.workflow?.name ?? '',
      node: err.node?.name ?? e.execution?.lastNodeExecuted ?? '',
      execution_url: e.execution?.url ?? '',
      execution_id: e.execution?.id ?? '',
    },
  },
}];
